83	func TestRegisterCreatesAndPersists(t *testing.T) {
84		path := filepath.Join(t.TempDir(), "nested", "registry.json")
85	
86		reg, existed, err := Load(path)
87		if err != nil {
88			t.Fatal(err)
89		}
90		if existed {
91			t.Fatal("registry should not exist yet")
92		}
93		out, err := Register(reg, Input{Batch: "B-1", Product: "P-7", Quantity: 120, Unit: "kg"})
94		if err != nil {
95			t.Fatal(err)
96		}
97		if !out.Created || out.Batch.Quantity != 120 {
98			t.Fatalf("unexpected outcome: %+v", out)
99		}
100		if err := Save(path, reg); err != nil {
101			t.Fatal(err)
102		}
103	
104		// Restart: old batch must still be recognized.
105		reg2, existed, err := Load(path)
106		if err != nil || !existed {
107			t.Fatalf("reload: existed=%v err=%v", existed, err)
108		}
109		out, err = Register(reg2, Input{Batch: "B-1", Product: "P-7", Quantity: 120, Unit: "kg"})
110		if err != nil {
111			t.Fatal(err)
112		}
113		if out.Created {
114			t.Fatal("identical repeat should be a duplicate, not a create")
115		}
116	
117		// A second batch keeps the first one intact.
118		_, err = Register(reg2, Input{Batch: "B-2", Product: "P-8", Quantity: 1, Unit: "box"})
119		if err != nil {
120			t.Fatal(err)
121		}
122		if err := Save(path, reg2); err != nil {
123			t.Fatal(err)
124		}
125		data, err := os.ReadFile(path)
126		if err != nil {
127			t.Fatal(err)
128		}
129		var parsed Registry
130		if err := json.Unmarshal(data, &parsed); err != nil {
131			t.Fatal(err)
132		}
133		if len(parsed.Batches) != 2 || parsed.Version != FormatVersion {
134			t.Fatalf("unexpected persisted content: %s", data)
135		}
136	}
