168	func TestConflictNamesFieldsAndDoesNotMutate(t *testing.T) {
169		path := filepath.Join(t.TempDir(), "registry.json")
170		writeRegistry(t, path, `{"version":1,"batches":[{"batch":"B-1","product":"P-7","quantity":120,"unit":"kg"},{"batch":"B-9","product":"P-9","quantity":3,"unit":"box"}]}`)
171	
172		cases := []struct {
173			name       string
174			in         Input
175			wantFields []string
176		}{
177			{"product", Input{Batch: "B-1", Product: "P-8", Quantity: 120, Unit: "kg"}, []string{"product"}},
178			{"quantity", Input{Batch: "B-1", Product: "P-7", Quantity: 121, Unit: "kg"}, []string{"quantity"}},
179			{"unit", Input{Batch: "B-1", Product: "P-7", Quantity: 120, Unit: "g"}, []string{"unit"}},
180			{"all", Input{Batch: "B-1", Product: "X", Quantity: 1, Unit: "Y"}, []string{"product", "quantity", "unit"}},
181		}
182		original, err := os.ReadFile(path)
183		if err != nil {
