			if !errors.As(err, &se) {
				t.Fatalf("got %v, want SaveError", err)
			}
			if se.Batch != "" {
				t.Fatalf("no batch id may be attached, got %q", se.Batch)
			}
			if strings.Contains(err.Error(), "batch \"") {
